struct Scanner {
    istream &in;
    size_t id;
    vector<char> buf;

    Scanner() : in(cin), id(0), buf() {}

    optional<string> next_line() {
        string res;
        if (!std::getline(in, res)) {
            if (in.eof()) return nullopt;
            throw runtime_error("error in read_line");
        }
        return res;
    }

    template <class T>
    optional<T> next() {
        while (buf.empty()) {
            auto line_opt = next_line();
            if (!line_opt.has_value()) return nullopt;
            string r = *line_opt;
            // trim
            size_t start = r.find_first_not_of(" \t\r\n");
            if (start == string::npos) {
                buf.clear();
                continue;
            }
            size_t end = r.find_last_not_of(" \t\r\n");
            string trimmed = r.substr(start, end - start + 1);
            buf.assign(trimmed.begin(), trimmed.end());
            id = 0;
        }
        size_t l = id;
        assert(buf[l] != ' ');
        size_t n = buf.size();
        size_t r = l;
        while (r < n && buf[r] != ' ') {
            r++;
        }
        string token(buf.begin() + l, buf.begin() + r);
        T value;
        std::istringstream iss(token);
        if (!(iss >> value)) {
            throw runtime_error("parse error");
        }
        while (r < n && buf[r] == ' ') {
            r++;
        }
        if (r == n) {
            buf.clear();
        } else {
            id = r;
        }
        return value;
    }

    template <class T>
    T ne() {
        auto v = next<T>();
        if (!v.has_value()) {
            throw runtime_error("unexpected end of input");
        }
        return *v;
    }
};

